function result=v4TrackAStage55DualHypothesisDecode(packet,c,p)
anchor=v4TrackAPointAnchor(packet,c);if abs(anchor.cfoBins)>p.highShiftThresholdBins,result=v4TrackAStage55PreambleAdaptiveDecode(packet,c,p);result.receiverMode='HIGH_SHIFT_STATIC';result.algorithmVersion='Stage55-A-causal-dual-hypothesis-v11';return,end
medianResult=v4TrackAStage55HybridDecode(packet,c,p);consensusResult=v4TrackAStage55ConsensusHybridDecode(packet,c,p);s=packet.schedule;detected=nan(23,1);estimated=nan(23,1);accepted=false(23,1);labels=nan(23,1);chosen=zeros(23,1,'uint8');
for d=1:23,row=s.dataRows(d);first=s.startSample(row)+1;rx=packet.rx(first:first+c.samplesPerSymbol-1).';n=0:c.samplesPerSymbol-1;cfos=[medianResult.estimatedCfoBins(d) consensusResult.estimatedCfoBins(d)];score=zeros(2,1);decision=zeros(2,1);for h=1:2,y=rx.*exp(-1i*2*pi*cfos(h)*n/c.samplesPerSymbol);z=v4SymbolLikelihood(y,c,packet.noiseVariance);score(h)=z.peakRatio;decision(h)=z.physicalBin;end;[~,h]=max(score);chosen(d)=h;detected(d)=decision(h);estimated(d)=cfos(h);if h==1,accepted(d)=medianResult.virtualPilotAccepted(d);labels(d)=medianResult.vpUsedLabel(d);else,accepted(d)=consensusResult.virtualPilotAccepted(d);labels(d)=consensusResult.vpUsedLabel(d);end;end
result=struct('methodName','Stage55-VP-quality-SER-SF12-noLDRO','algorithmVersion','Stage55-A-causal-dual-hypothesis-v11','receiverMode','LOW_SHIFT_DUAL_HYPOTHESIS','detectedPhysicalBins',detected,'estimatedCfoBins',estimated,'virtualPilotAccepted',accepted,'vpUsedLabel',labels,'chosenHypothesis',chosen,'usesTruth',false,'usesHamming',false,'usesMidambleObservation',false);
end
